from collections import deque

MAX_ACTIONS = 1000


def _norm(atoms):
    """Coerce atoms/TaskView inputs into a set of plain tuples."""
    out = set()
    if atoms is None:
        return out
    if isinstance(atoms, dict):
        atoms = list(atoms.keys())
    for a in atoms:
        try:
            out.add(tuple(a))
        except TypeError:
            continue
    return out


def _by_type(objects, tname):
    names = set()
