            n, t = pair
        except Exception:
            continue
        if t == tname or (tname == "locatable" and t in ("man", "nut", "spanner")):
            names.add(n)
    return names


def _walk_actions(state, locs, mans):
    acts = []
    for (p, a, b) in state:
        if p != "link":
            continue
        if a not in locs or b not in locs:
            continue
        for m in mans:
            if ("at", m, a) in state:
                acts.append(("walk", (a, b, m)))
    return acts


def _pickup_actions(state, locs, spanners, mans):
    acts = []
    for (p, l, s) in state:
        if p != "at" or s not in spanners or l not in locs:
            continue
        for m in mans:
            if ("at", m, l) in state and ("at", s, l) in state:
                acts.append(("pickup_spanner", (l, s, m)))
    return acts


def _tighten_actions(state, locs, spanners, nuts, mans):
    acts = []
    for m in mans:
        carrying = [s for (p, mm, s) in state
